ALTER TABLE "app"."notifications" DROP CONSTRAINT "notification_target";--> statement-breakpoint
ALTER TABLE "app"."notifications" ADD CONSTRAINT "notification_target" CHECK (("app"."notifications"."kind" = 'otp' AND "app"."notifications"."challenge_id" IS NOT NULL AND "app"."notifications"."booking_id" IS NULL AND "app"."notifications"."booking_version" IS NULL AND "app"."notifications"."scheduled_at" IS NULL) OR ("app"."notifications"."kind" IN ('confirmation','reminder') AND "app"."notifications"."challenge_id" IS NULL AND "app"."notifications"."booking_id" IS NOT NULL AND "app"."notifications"."booking_version" IS NOT NULL AND "app"."notifications"."booking_version" > 0 AND "app"."notifications"."scheduled_at" IS NOT NULL));